-- Nieuwe B2B-mailteksten (eerste mail + opvolgmail). Ook als de B2B-instellingen al eens zijn opgeslagen.
UPDATE settings SET value = jsonb_set(value, '{templates}', '{"eerste": {"subject": "Tafellampen bij {bedrijf}?", "body": "Hoi,\n\n{intro}Ik zag dat jullie bij {bedrijf} nog geen draadloze tafellampen gebruiken. Daarom een korte mail van mij.\n\nBij Lumiq maken we draadloze tafellampen voor de horeca. Het verschil met kaarsen:\n- geen kaarsvet op tafels en tafelkleden, en geen open vuur\n- met één tik vanaf de bar alle lampen tegelijk aan, van 20 tot 200 stuks\n- tot 24 uur licht per lading, draadloos opladen zonder stekker\n- ook op het terras (IP44), met 2 jaar garantie en Nederlandse support\n\nAlle 12 series en 64 modellen staan in onze catalogus:\n{catalogus}\n\nZullen we even bellen? In vijf minuten vertel ik je hoe het werkt. Reageer gewoon op deze mail met een moment dat jou uitkomt.\n\nGroet,\n{afzender}"}, "opvolging": {"subject": "Re: Tafellampen bij {bedrijf}?", "body": "Hoi,\n\nEven een kort berichtje na mijn vorige mail. Veel zaken stappen dit najaar over van kaarsen naar draadloze lampen: geen kaarsvet meer, en elke avond met één tik de hele zaak sfeervol aan.\n\nDe catalogus staat hier:\n{catalogus}\n\nHeb je deze week vijf minuten om even te bellen? Je kunt mij ook direct bellen op {telefoon}.\n\nNiet interessant? Laat het even weten, dan hoor je niets meer van ons.\n\nGroet,\n{afzender}"}}'::jsonb), updated_at = NOW() WHERE key = 'b2b';
